// CVEs in kev_entries and cve_watch that were never checked, or not checked for 3 days.
// Alternate KEV and CVE Watch rows so neither list waits for the other to finish.
const pick = (n) => $(n).all().map(i => String(i.json?.cve_id || '').toUpperCase()).filter(id => /^CVE-\d{4}-\d{4,}$/.test(id));
const a = pick('Get KEV to check'), b = pick('Get CVE Watch to check'), ids = new Set();
for (let k = 0; k < Math.max(a.length, b.length); k++) { if (a[k]) ids.add(a[k]); if (b[k]) ids.add(b[k]); }
const list = [...ids].slice(0, 150);
if (!list.length) return [];
// Vulnrichment layout: <year>/<number div 1000>xxx/<CVE id>.json on the 'develop' branch
return list.map(id => { const [, y, n] = id.match(/^CVE-(\d{4})-(\d+)$/);
  return { json: { cve_id: id, url: `https://raw.githubusercontent.com/cisagov/vulnrichment/develop/${y}/${Math.floor(Number(n) / 1000)}xxx/${id}.json` } }; });

// Read CISA's SSVC block (ADP container 'CISA-ADP', metrics[].other.type === 'ssvc').
// 404 = no Vulnrichment record yet -> not_assessed. Any other failure (rate limit, network) is skipped
// so the CVE is simply retried next run instead of being wrongly marked not_assessed.
const req = $('Rows to check').all().map(i => i.json);
const res = $input.all();
const rows = []; let skipped = 0;
req.forEach((r, i) => {
  const x = res[i]?.json || {};
  const code = Number(x.statusCode);
  const out = { cve_id: r.cve_id, exploitation: null, automatable: null, technical_impact: null, status: 'not_assessed', assessed_at: null };
  if (code === 404) { rows.push(out); return; }
  if (code !== 200) { skipped++; return; }
  let j; try { const b = x.body ?? x.data; j = typeof b === 'string' ? JSON.parse(b) : b; } catch (e) { skipped++; return; }
  for (const adp of j?.containers?.adp || []) {
    if ((adp.providerMetadata?.shortName || '') !== 'CISA-ADP') continue;
    for (const m of adp.metrics || []) {
      const o = m?.other; if (o?.type !== 'ssvc') continue;
      for (const opt of o.content?.options || []) {
        const [k, v] = Object.entries(opt || {})[0] || []; const val = String(v || '').toLowerCase();
        if (k === 'Exploitation' && ['none', 'poc', 'active'].includes(val)) out.exploitation = val;
        if (k === 'Automatable' && ['no', 'yes'].includes(val)) out.automatable = val;
        if (k === 'Technical Impact' && ['partial', 'total'].includes(val)) out.technical_impact = val;
      }
      if (o.content?.timestamp) out.assessed_at = o.content.timestamp;
    }
  }
  if (out.exploitation || out.automatable) out.status = 'assessed';
  rows.push(out);
});
return [{ json: { rows, assessed: rows.filter(r => r.status === 'assessed').length, not_assessed: rows.filter(r => r.status === 'not_assessed').length, skipped } }];
